const { GAME, HISTORY, mulberry32 } = require('./data.js');

function analyzeArea(draws, area, windowSize) {
  const recent = windowSize > 0 ? draws.slice(0, windowSize) : draws;
  const pool = area.max - area.min + 1;
  const freq = new Array(pool + 1).fill(0);
  const omission = new Array(pool + 1).fill(recent.length);
  recent.forEach((d, idx) => {
    d.areas[area.key].forEach(n => freq[n]++);
  });
  for (let i = recent.length - 1; i >= 0; i--) {
    recent[i].areas[area.key].forEach(n => { omission[n] = i; });
  }
  const meanFreq = (recent.length * area.pick) / pool;
  const gap = pool / area.pick - 1;
  const nums = [];
  for (let n = area.min; n <= area.max; n++) nums.push(n);

  const hot = nums.filter(n => freq[n] >= meanFreq * 1.45).sort((a, b) => freq[b] - freq[a]).slice(0, 8);
  const cold = nums.filter(n => freq[n] <= meanFreq * 0.45 || omission[n] >= gap * 3)
    .sort((a, b) => omission[b] - omission[a]).slice(0, 8);
  const coldSet = new Set(cold);

  const sumSeries = recent.map(d => d.areas[area.key].reduce((a, b) => a + b, 0));
  const maxOmissionNums = [...nums].sort((a, b) => omission[b] - omission[a]).slice(0, 6);

  return { area, freq, omission, meanFreq, gap, hot, cold, coldSet, sumSeries, maxOmissionNums, window: recent.length };
}

function analyze(gameId, windowSize) {
  const game = GAME[gameId];
  const map = {};
  game.areas.forEach(area => {
    map[area.key] = analyzeArea(HISTORY[gameId], area, windowSize);
  });
  return map;
}

function weightedPick(area, k, weightFn, rng, exclude = new Set()) {
  const items = [];
  for (let n = area.min; n <= area.max; n++) {
    if (exclude.has(n)) continue;
    const w = Math.max(weightFn(n), 1e-6);
    items.push({ n, key: -Math.log(rng()) / w });
  }
  items.sort((a, b) => a.key - b.key);
  return items.slice(0, k).map(i => i.n).sort((a, b) => a - b);
}

function zoneBounds(area) {
  const size = Math.ceil((area.max - area.min + 1) / area.zones);
  const bounds = [];
  for (let i = 0; i < area.zones; i++) {
    bounds.push([area.min + i * size, Math.min(area.min + (i + 1) * size - 1, area.max)]);
  }
  return bounds;
}

function zoneCounts(area, pick) {
  return zoneBounds(area).map(([lo, hi]) => pick.filter(n => n >= lo && n <= hi).length);
}

function maxRun(pick) {
  let run = 1, max = 1;
  for (let i = 1; i < pick.length; i++) {
    run = pick[i] === pick[i - 1] + 1 ? run + 1 : 1;
    max = Math.max(max, run);
  }
  return max;
}

function passesFilters(game, area, pick, opts) {
  if (area.pick < 5) return true;
  if (opts.sumRange) {
    const sum = pick.reduce((a, b) => a + b, 0);
    if (sum < game.sumIdeal[0] || sum > game.sumIdeal[1]) return false;
  }
  if (opts.oddEven) {
    const odd = pick.filter(n => n % 2 === 1).length;
    if (odd < game.oddIdeal[0] || odd > game.oddIdeal[1]) return false;
  }
  if (opts.zoneBalance) {
    const counts = zoneCounts(area, pick);
    if (counts.some(c => c === 0)) return false;
  }
  if (opts.noTripleRun && maxRun(pick) >= 3) return false;
  return true;
}

function scorePick(area, pick, analysis) {
  const sum = pick.reduce((a, b) => a + b, 0);
  const mid = (analysis.sumSeries.reduce((a, b) => a + b, 0) / Math.max(analysis.sumSeries.length, 1));
  const dist = Math.max(Math.abs(sum - mid), 1);
  const sumScore = Math.exp(-Math.pow(dist / (mid * 0.22), 2));
  const counts = zoneCounts(area, pick);
  const even = 1 - (Math.max(...counts) - Math.min(...counts)) / area.pick;
  const odd = pick.filter(n => n % 2 === 1).length;
  const oddScore = 1 - Math.abs(odd - area.pick / 2) / (area.pick / 2);
  const run = maxRun(pick);
  const runScore = run >= 4 ? 0.2 : run === 3 ? 0.6 : 1;
  const coldCount = pick.filter(n => analysis.coldSet.has(n)).length;
  const mixScore = coldCount >= 1 && coldCount <= 3 ? 1 : coldCount === 0 ? 0.6 : 0.5;
  return sumScore * 0.3 + even * 0.25 + Math.max(oddScore, 0) * 0.2 + runScore * 0.1 + mixScore * 0.15;
}

function weightFor(strategy, analysis) {
  const { freq, omission, gap, meanFreq } = analysis;
  switch (strategy) {
    case 'hot':
      return n => 1 + (freq[n] / (meanFreq + 1)) * 5;
    case 'cold':
      return n => 1 + (omission[n] / (gap + 1)) * 4;
    case 'omission':
      return n => 1.2 + Math.exp(-Math.pow((omission[n] / (gap + 1)) - 1.8, 2) / 0.9) * 8;
    case 'random':
      return () => 1;
    case 'smart':
    default:
      return n => 1 + (freq[n] / (meanFreq + 1)) * 2;
  }
}

function generateAreaPick(game, area, analysis, strategy, opts, rng) {
  const must = (opts.must && opts.must[area.key]) || [];
  const banned = new Set((opts.exclude && opts.exclude[area.key]) || []);
  must.forEach(n => banned.delete(n));
  const remain = area.pick - must.length;
  if (remain < 0) throw new Error(`${area.label}定胆数量超过选号数量`);
  const poolSize = area.max - area.min + 1;
  if (poolSize - banned.size - must.length < remain) {
    throw new Error(`${area.label}杀号过多，剩余号码不足`);
  }

  const tries = 60;
  let fallback = null;
  for (let t = 0; t < tries; t++) {
    const need = [...banned, ...must];
    const rest = weightedPick(area, remain, weightFor(strategy === 'smart' ? 'smart' : strategy, analysis), rng, new Set(need));
    const pick = [...must, ...rest].sort((a, b) => a - b);
    if (fallback === null) fallback = pick;
    if (passesFilters(game, area, pick, opts)) {
      if (strategy === 'smart' && area.pick >= 5) {
        return { pick, score: scorePick(area, pick, analysis) };
      }
      return { pick, score: null };
    }
  }
  if (strategy === 'smart' && area.pick >= 5) {
    let best = fallback, bestScore = -1;
    for (let t = 0; t < 30; t++) {
      const need = [...banned, ...must];
      const rest = weightedPick(area, remain, weightFor('smart', analysis), rng, new Set(need));
      const cand = [...must, ...rest].sort((a, b) => a - b);
      const s = scorePick(area, cand, analysis);
      if (s > bestScore) { bestScore = s; best = cand; }
    }
    return { pick: best, score: bestScore };
  }
  return { pick: fallback, score: null };
}

function generatePick(gameId, strategy, opts, seed) {
  const game = GAME[gameId];
  const rng = mulberry32(seed >>> 0);
  const analysisMap = analyze(gameId, opts.windowSize);
  const areas = {};
  let score = null;
  game.areas.forEach(area => {
    const r = generateAreaPick(game, area, analysisMap[area.key], strategy, opts, rng);
    areas[area.key] = r.pick;
    if (r.score !== null && area.key === game.main) score = r.score;
  });
  return { game: gameId, strategy, areas, score, ts: Date.now() };
}

function prizeInfo(gameId, mainHit, specialHit) {
  if (gameId === 'ssq') {
    if (mainHit === 6 && specialHit === 1) return '一等奖';
    if (mainHit === 6) return '二等奖';
    if (mainHit === 5 && specialHit === 1) return '三等奖';
    if (mainHit === 5 || (mainHit === 4 && specialHit === 1)) return '四等奖';
    if (mainHit === 4 || (mainHit === 3 && specialHit === 1)) return '五等奖';
    if (specialHit === 1) return '六等奖';
    return '未中奖';
  }
  if (mainHit === 5 && specialHit === 2) return '一等奖';
  if (mainHit === 5 && specialHit === 1) return '二等奖';
  if (mainHit === 5) return '三等奖';
  if (mainHit === 4 && specialHit === 2) return '四等奖';
  if (mainHit === 4 && specialHit === 1) return '五等奖';
  if (mainHit === 3 && specialHit === 2) return '六等奖';
  if (mainHit === 4) return '七等奖';
  if ((mainHit === 3 && specialHit === 1) || (mainHit === 2 && specialHit === 2)) return '八等奖';
  if ((mainHit === 3 && specialHit === 0) || (mainHit === 2 && specialHit === 1)
    || (mainHit === 1 && specialHit === 2) || (mainHit === 0 && specialHit === 2)) return '九等奖';
  return '未中奖';
}

module.exports = { analyze, generatePick, prizeInfo };
